        `}function ll(){const t=[{key:"Purchase Request Generated",label:"Request Created",desc:"Purchase Request automatically compiled",time:Y.timestamps.requestCreated},{key:"Payment Verified",label:"Payment Verified",desc:"Accounts cleared invoice wire",time:Y.timestamps.paymentVerified},{key:"QR Code Generated",label:"QR Code Generated",desc:"Secure webhook QR compiled",time:Y.timestamps.qrGenerated},{key:"Order Sent",label:"Order Dispatched",desc:"PO sent to supplier API & WhatsApp",time:Y.timestamps.orderSent},{key:"Supplier Accepted",label:"Supplier Accepted",desc:"BK Foods approved logistics queue",time:Y.timestamps.supplierAccepted},{key:"Preparing",label:"Preparing Order",desc:"Packing fresh inventory lines",time:Y.timestamps.preparing},{key:"Packed",label:"Packed & Ready",desc:"Order sealed at Ichhapore facility",time:Y.timestamps.packed},{key:"Dispatched",label:"Out for Delivery",desc:"En route via NH-48",time:Y.timestamps.dispatched},{key:"Delivered",label:"Delivered",desc:"Arrived at outlet loading dock",time:Y.timestamps.delivered},{key:"Inventory Updated",label:"Inventory Updated",desc:"Materials verified & restocked",time:Y.timestamps.inventoryUpdated}];let e=t.findIndex(o=>o.key===Y.status);e===-1&&(Y.status==="Payment Completed"?e=0:e=-1);let a=e;return Y.paymentVerified&&a<1&&(a=1),Y.qrGenerated&&a<2&&(a=2),`
